const cellRootPrefix = 'root-';

interface CellReactRoot {
  unmount?: () => void;
}

export function getCellRootKey(row: number, col: number) {
  return `${cellRootPrefix}${row}_${col}`;
}

export function releaseCellReactRoots(target: Record<string, any>, keepKey?: string) {
  Object.keys(target).forEach((key) => {
    if (!key.startsWith(cellRootPrefix) || key === keepKey) return;
    const root = target[key] as CellReactRoot | undefined;
    root?.unmount?.();
    delete target[key];
  });
}

export function releaseTableCellReactRoots(rootElement?: HTMLElement | null) {
  rootElement?.querySelectorAll('td').forEach((cell) => releaseCellReactRoots(cell as any));
}

interface TableWithDestroyHook {
  rootElement?: HTMLElement | null;
  addHookOnce: (...args: any[]) => void;
}

const registeredTables = new WeakSet<object>();

export function registerTableCellRootCleanup(table: TableWithDestroyHook) {
  if (registeredTables.has(table)) return;
  registeredTables.add(table);
  table.addHookOnce('beforeDestroy', () => {
    releaseTableCellReactRoots(table.rootElement);
    registeredTables.delete(table);
  });
}

