const dom = new JSDOM('<!doctype html><html><body><table><tbody><tr><td></td></tr></tbody></table></body></html>', {
  url: 'http://localhost/'
});

Object.assign(globalThis, {
  window: dom.window,
  document: dom.window.document,
  navigator: dom.window.navigator,
  Node: dom.window.Node,
  Element: dom.window.Element,
  HTMLElement: dom.window.HTMLElement,
  HTMLTableCellElement: dom.window.HTMLTableCellElement,
  MutationObserver: dom.window.MutationObserver,
  getComputedStyle: dom.window.getComputedStyle.bind(dom.window)
});

(require.extensions as any)['.less'] = () => undefined;

const Module = require('node:module');
const originalLoad = Module._load;
Module._load = function load(request: string, parent: unknown, isMain: boolean) {
  if (request === '@newgrand/udp-ui/es/functionalComponent/table/util') {
    return {
      stopPropagation(event: Event & { nativeEvent?: Event }) {
        event.stopPropagation();
        event.nativeEvent?.stopImmediatePropagation?.();
      }
    };
  }
  return originalLoad.call(this, request, parent, isMain);
};

const { default: treeRender } = require('../src/components/report/preview/plugins/treeRender');
Module._load = originalLoad;

const TD = document.querySelector('td') as any;
const cellProperties = {
  row: 0,
  col: 0,
  children: [1],
  expanded: false,
  treeLevel: 1,
  formatData: 'root',
  className: ''
};
const hot = {
  getPlugin(name: string) {
    assert.equal(name, 'mergeCells');
    return { mergedCellsCollection: { get: () => null } };
  },
  getRowHeight: () => 30,
  getColWidth: () => 100,
  getCellMeta: () => cellProperties,
  getSettings: () => ({ fixedRowsTop: 0 })
};

async function testFirstRender() {
  treeRender.call(hot, hot, TD, 0, 0, 0, 'root', cellProperties);
  cellProperties.formatData = 'latest root';
  treeRender.call(hot, hot, TD, 0, 0, 0, 'root', cellProperties);
  await Promise.resolve();

  assert.ok(TD.querySelector('.treeHeader'), 'the row-0 tree component must be committed before the next paint');
  assert.ok(TD.querySelector('.icon-collapsed'), 'the row-0 collapsed icon must be visible on the first render');
  assert.match(TD.textContent, /latest root/, 'a rerender before the microtask must commit the latest tree properties');

  TD['root-0_0'].unmount();
  dom.window.close();
  console.log('tree preview first render tests passed');
}

testFirstRender();

