import cellTypes from '@/constants/cellTypes';
import { HotTableClass } from '@handsontable/react';
import { NG, useRefCallback, useSelector } from '@newgrand/udp-ui';
import { useLocation } from '@umijs/max';
import { Tabs } from 'antd';
import Handsontable from 'handsontable';
import { useEffect, useMemo, useState } from 'react';
import chartRender from '../plugins/chartRender';
import imageRender from '../plugins/imageRender';
import slashRender from '../plugins/slashRender';
import textRender from '../plugins/textRender';
import treeRender from '../plugins/treeRender';
import { handleLoadGlobalSettings } from './utils';

interface PreviewTableSheetsProps {
  className?: string;
  tableRef: { current: HotTableClass | null };
  noSheets?: boolean;
}
const PreviewTableSheets: React.FC<PreviewTableSheetsProps> = ({ className, tableRef, noSheets = false }) => {
  Handsontable.cellTypes.registerCellType(cellTypes.text, {
    renderer: textRender
  });
  Handsontable.cellTypes.registerCellType(cellTypes.chart, {
    renderer: chartRender
  });
  Handsontable.cellTypes.registerCellType(cellTypes.slash, {
    renderer: slashRender
  });
  Handsontable.cellTypes.registerCellType(cellTypes.tree, {
    renderer: treeRender,
    editor: false
  });
  Handsontable.cellTypes.registerCellType(cellTypes.image, {
    renderer: imageRender
  });

  const [tabItems, setTabItems] = useState<any[]>([]);

  const { defaultSheet, sheets, userLayouts } = useSelector(
    (state) => {
      const s = state[NG.getPageInstance().props.getDvaName()];
      return {
        defaultSheet: s.defaultSheet,
        sheets: s.sheets,
        userLayouts: s.userLayouts
      };
    },
    (prev, next) =>
      prev.defaultSheet === next.defaultSheet &&
      prev.sheets === next.sheets &&
      prev.userLayouts === next.userLayouts
  );

  const { pathname } = useLocation();

  /**
   * 获取hotInstance
   */
  function getHotInstance(): HotTableClass | undefined {
    return tableRef.current ?? undefined;
  }

  const onChange = async (key: string) => {
    window.dispatchEvent(new CustomEvent('reportPreviewBeforeSheetChange', { detail: { sheetKey: defaultSheet } }));

    NG.getPageInstance().umiDispatch({
      type: 'updateHotLoading',
      payload: true
    });

    await NG.delay(300);

    NG.getPageInstance().umiDispatch({
      type: 'updateDefaultSheet',
      payload: key
    });

    // 工作流页面的切换逻辑
    if (pathname.includes('reportWorkFlow')) {
      NG.getPageInstance().umiDispatch({
        type: 'changeReportSheet',
        payload: sheets[key]
      });
      NG.getPageInstance().umiDispatch({
        type: 'updateHotLoading',
        payload: false
      });
    }
  };

  // sheets 或 userLayouts（行列布局调整）变化时重新渲染
  // 使用 useMemo 稳定化 dep，避免 useSelector 整体 state 刷新导致的假触发
  const sheetsKey = useMemo(() => sheets, [sheets]);
  const userLayoutsKey = useMemo(() => userLayouts, [userLayouts]);

  useEffect(() => {
    if (!tableRef.current) return;
    if (!sheets || (sheets && sheets.length <= 0)) return;
    handleLoadFetchedData(sheets);
  }, [sheetsKey, tableRef.current, userLayoutsKey]);

  /**
   * 处理获取到的数据
   *  */
  const handleLoadFetchedData = useRefCallback((data) => {
    // tab标签页
    const sheetTabs: any[] = [];
    // 1、处理sheet列表 显示成tab
    data?.forEach((sheet, index) => {
      sheetTabs.push({
        label: sheet.sheetName,
        key: sheet.sheetKey || index.toString()
      });
    });

    // 2、设置当前点击、活跃的sheet标签
    setTabItems(sheetTabs);

    const legalKey = defaultSheet ?? '0';

    // 将useLayout配置合并到globalSettings
    const newGlobalSettings = NG.deepCopy(data[legalKey]?.globalSettings ?? {});
    const useLayout = userLayouts?.find((item) => item.sheetKey === legalKey);
    if (useLayout) {
      Object.assign(newGlobalSettings, useLayout.layoutConfig);
    }
    // 3、加载当前sheet数据
    // 4、加载设置
    const hot = getHotInstance();
    if (!hot) return;
    handleLoadGlobalSettings(hot, data[legalKey]?.cells, newGlobalSettings);
  });

  return (
    <Tabs
      // 只是隐藏
      hidden={noSheets}
      className={className}
      onChange={onChange}
      activeKey={defaultSheet ?? '0'}
      type="card"
      items={tabItems}
    />
  );
};

export default PreviewTableSheets;

