const emptySettings = createVirtualizedMergeCellsSettings();
assert.deepEqual(emptySettings, { virtualized: true, cells: [] });
assert.notEqual(
  emptySettings.cells,
  createVirtualizedMergeCellsSettings().cells,
  'empty settings calls must not share a mutable cells array'
);

console.log('preview merge virtualization tests passed');

