import Handsontable from 'handsontable';
import type { ReactNode } from 'react';
import { flushSync } from 'react-dom';
import type { Root } from 'react-dom/client';
import { createRoot } from 'react-dom/client';
import { empty } from '../../design/components/customTable/plugins/utils/hot-utils';
import { getCellRootKey, releaseCellReactRoots } from './cellRootLifecycle';

export const getBorderByDirection = (direction, border, TD: HTMLTableCellElement) => {
  const borderClass = `htBorder_${direction.charAt(0).toUpperCase() + direction.slice(1)}_${border?.width ?? 1}_${(
    border?.color ?? '#000'
  ).slice(1)}`;

  if (['top', 'bottom', 'left', 'right'].includes(direction)) {
    TD.classList.add(borderClass);
  }
};

/**
 * 判断当前单元格是否在冻结区域
 * 是的话，缓存react组件，防止重复渲染
 */
export function isInFrozen(
  row: number,
  col: number,
  cellProperties: Handsontable.CellProperties,
  hot: Handsontable.Core
) {
  // 如果fixedColumnsStart有值，代表有冻结
  if (cellProperties.fixedColumnsStart) {
    const fixedRowsStart = hot.getSettings().fixedRowsTop;
    if (row <= (fixedRowsStart ?? 0) && col <= (cellProperties.fixedColumnsStart ?? 0)) {
      return true;
    }
  }
  return false;
}

export function optimizeRender(TD, row, col, _lazyRender?: boolean) {
  const rootKey = getCellRootKey(row, col);
  releaseCellReactRoots(TD, rootKey);
  if (TD[rootKey]) return false;

  empty(TD);
  TD[rootKey] = createRoot(TD);
  return true;
}

interface DeferredRootRender {
  content: ReactNode;
  isCurrentRoot: () => boolean;
}

const deferredRootRenders = new WeakMap<Root, DeferredRootRender>();

export function renderCellReactRoot(
  root: Root,
  content: ReactNode,
  deferSynchronousCommit = false,
  isCurrentRoot: () => boolean = () => true
) {
  const pendingRender = deferredRootRenders.get(root);
  if (!deferSynchronousCommit && !pendingRender) {
    root.render(content);
    return;
  }

  deferredRootRenders.set(root, {
    content,
    isCurrentRoot: pendingRender?.isCurrentRoot ?? isCurrentRoot
  });
  if (pendingRender) return;

  // Initial tree rendering is triggered by a React effect, where flushSync is
  // not allowed. Commit row 0 in the next microtask: outside React's lifecycle
  // but still before the browser's next paint.
  queueMicrotask(() => {
    const latestRender = deferredRootRenders.get(root);
    deferredRootRenders.delete(root);
    if (latestRender?.isCurrentRoot()) {
      flushSync(() => root.render(latestRender.content));
    }
  });
}

export function getRenderCellProperties(
  instance: Handsontable.Core,
  row: number,
  col: number,
  cellProperties: Handsontable.CellProperties
): (Handsontable.CellProperties & { row: number; col: number }) | null {
  if (row === cellProperties.row && col === cellProperties.col) {
    return cellProperties as Handsontable.CellProperties & { row: number; col: number };
  }

